/* rfp_jac:(x,p)->(jac_g_x,g) */
static int casadi_f1(const casadi_real** arg, casadi_real** res, casadi_int* iw, casadi_real* w, int mem) {
  casadi_real w0, w1;
  /* #0: @0 = input[0][0] */
  w0 = arg[0] ? arg[0][0] : 0;
  /* #1: @1 = (2.*@0) */
  w1 = (2.* w0 );
  /* #2: output[0][0] = @1 */
  if (res[0]) res[0][0] = w1;
  /* #3: @0 = sq(@0) */
  w0 = casadi_sq( w0 );
  /* #4: @1 = input[1][0] */
  w1 = arg[1] ? arg[1][0] : 0;
  /* #5: @0 = (@0-@1) */
  w0 -= w1;
  /* #6: output[1][0] = @0 */
  if (res[1]) res[1][0] = w0;
  return 0;
}

/* rfp:(x0,p)->(x) */
static int casadi_f0(const casadi_real** arg, casadi_real** res, casadi_int* iw, casadi_real* w, int mem) {
  casadi_int iter;
  struct casadi_newton_mem m;
  m.n = 1;
  m.abstol = 1e-12;
  m.abstol_step = 1e-12;
  m.max_step = 0.5;
  m.x = w;
  m.g = w+1;
  m.jac_g_x = w+2;
  m.sp_a = casadi_s0;
  m.sp_v = casadi_s0;
  m.sp_r = casadi_s0;
  m.prinv = casadi_s1;
  m.pc = casadi_s1;
  m.lin_w = w+3;
  m.lin_v = w+5;
  m.lin_r = w+6;
  m.lin_beta = w+7;
  /* Get the initial guess */
  casadi_copy(arg[0], 1, m.x);
  for (iter=0; iter<1000; ++iter) {
    /* (re)calculate f and J */
    arg[2] = m.x;
    arg[3] = arg[1];
    res[1] = m.jac_g_x;
    res[2] = m.g;
    if (casadi_f1(arg+2, res+1, iw, w+8, 0)) return 1;
    if (casadi_newton(&m)) break;
  }
  /* Get the solution */
  casadi_copy(m.x, 1, res[0]);
  return 0;
}

